using System;using System.IO;using System.Text;using System.Windows;using System.Windows.Controls;
namespace MDNote {public partial class MainWindow {
sealed class OpenEncodingChoice {internal string Name;internal int? CodePage;public override string ToString(){return Name;}}
void BuildOpenEncodingMenu(MenuItem file){var item=new MenuItem {Header=T("인코딩을 지정하여 열기…")};item.Click+=delegate{OpenWithEncoding();};file.Items.Insert(Math.Min(2,file.Items.Count),item);}
void OpenWithEncoding(){var files=new Microsoft.Win32.OpenFileDialog {Multiselect=true,Filter=T("Markdown / 텍스트|*.md;*.markdown;*.txt|모든 파일|*.*")};if(files.ShowDialog(this)!=true)return;var choices=new[]{new OpenEncodingChoice {Name=T("자동 감지")},new OpenEncodingChoice {Name="UTF-8",CodePage=65001},new OpenEncodingChoice {Name="UTF-16 LE",CodePage=1200},new OpenEncodingChoice {Name="UTF-16 BE",CodePage=1201},new OpenEncodingChoice {Name=T("한국어 (CP949)"),CodePage=949},new OpenEncodingChoice {Name=T("일본어 (Shift JIS)"),CodePage=932},new OpenEncodingChoice {Name=T("중국어 간체 (GBK)"),CodePage=936},new OpenEncodingChoice {Name=T("중국어 번체 (Big5)"),CodePage=950},new OpenEncodingChoice {Name=T("서유럽 (Windows-1252)"),CodePage=1252},new OpenEncodingChoice {Name="UTF-32 LE",CodePage=12000},new OpenEncodingChoice {Name="UTF-32 BE",CodePage=12001}};var dialog=new Window {Title=T("인코딩 지정"),Owner=this,Width=390,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Background,Foreground=Foreground,ShowInTaskbar=false};dialog.Resources.MergedDictionaries.Add(Resources);var panel=new StackPanel {Margin=new Thickness(20)};dialog.Content=panel;panel.Children.Add(new TextBlock {Text=T("파일을 읽을 인코딩을 선택하세요."),Margin=new Thickness(0,0,0,10)});var combo=new ComboBox {ItemsSource=choices,SelectedIndex=0,MinWidth=260,Margin=new Thickness(0,0,0,16)};panel.Children.Add(combo);var buttons=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};panel.Children.Add(buttons);var cancel=new Button {Content=T("취소"),IsCancel=true,MinWidth=70};buttons.Children.Add(cancel);var open=new Button {Content=T("열기"),IsDefault=true,MinWidth=70,Margin=new Thickness(6,0,0,0)};open.Click+=delegate{dialog.DialogResult=true;};buttons.Children.Add(open);if(dialog.ShowDialog()!=true)return;var chosen=(OpenEncodingChoice)combo.SelectedItem;foreach(string file in files.FileNames)EnqueueFileOperation(new FileOperation {Name=file,CodePage=chosen.CodePage});}
static string ReadTextFileEncodingVersion(string name,int codePage,out Encoding encoding,out string fingerprint){byte[] bytes;return ReadTextFileEncodingVersion(name,codePage,out encoding,out fingerprint,out bytes);}
static string ReadTextFileEncodingVersion(string name,int codePage,out Encoding encoding,out string fingerprint,out byte[] bytes){bytes=File.ReadAllBytes(name);fingerprint=FileVersion.Of(bytes);int bom=0,detected=0;if(bytes.Length>=4&&bytes[0]==0xFF&&bytes[1]==0xFE&&bytes[2]==0&&bytes[3]==0){bom=4;detected=12000;}else if(bytes.Length>=4&&bytes[0]==0&&bytes[1]==0&&bytes[2]==0xFE&&bytes[3]==0xFF){bom=4;detected=12001;}else if(bytes.Length>=3&&bytes[0]==0xEF&&bytes[1]==0xBB&&bytes[2]==0xBF){bom=3;detected=65001;}else if(bytes.Length>=2&&bytes[0]==0xFF&&bytes[1]==0xFE){bom=2;detected=1200;}else if(bytes.Length>=2&&bytes[0]==0xFE&&bytes[1]==0xFF){bom=2;detected=1201;}if(bom>0&&detected!=codePage)throw new InvalidDataException(TranslatedText(SavedLanguage(),"선택한 인코딩과 파일의 BOM이 다릅니다. 자동 감지 또는 BOM에 맞는 인코딩을 선택해 주세요."));switch(codePage){case 65001:encoding=new UTF8Encoding(bom>0,true);break;case 1200:encoding=new UnicodeEncoding(false,bom>0,true);break;case 1201:encoding=new UnicodeEncoding(true,bom>0,true);break;case 12000:encoding=new UTF32Encoding(false,bom>0,true);break;case 12001:encoding=new UTF32Encoding(true,bom>0,true);break;default:encoding=Encoding.GetEncoding(codePage,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback);break;}return encoding.GetString(bytes,bom,bytes.Length-bom);}
}}
